-- ---------------------------------------------------------------------
-- TEST-MODE FINALIZATION
-- Business/packing/master inserts above may create lifecycle rows directly
-- or through normal business triggers. For this test, lifecycle history must
-- start at exactly zero so only event_processor.py populates it from fresh
-- video_events. Master tables and order mappings remain intact.
-- ---------------------------------------------------------------------
DELETE FROM `order_lifecycle_events`;

-- No rows are inserted into any video_* table. The first inference run writes them.
COMMIT;

-- =====================================================================
-- VERIFICATION
-- =====================================================================
SELECT 'team_users' AS table_name, COUNT(*) AS row_count FROM team_users
UNION ALL SELECT 'zones', COUNT(*) FROM zones
UNION ALL SELECT 'conveyors', COUNT(*) FROM conveyors
UNION ALL SELECT 'customers', COUNT(*) FROM customers
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'pallets', COUNT(*) FROM pallets
UNION ALL SELECT 'docks', COUNT(*) FROM docks
UNION ALL SELECT 'trailers', COUNT(*) FROM trailers
UNION ALL SELECT 'trucks', COUNT(*) FROM trucks
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items
UNION ALL SELECT 'order_item_products', COUNT(*) FROM order_item_products
UNION ALL SELECT 'boxes', COUNT(*) FROM boxes
UNION ALL SELECT 'order_boxes', COUNT(*) FROM order_boxes
UNION ALL SELECT 'events', COUNT(*) FROM events
UNION ALL SELECT 'order_lifecycle_events', COUNT(*) FROM order_lifecycle_events
UNION ALL SELECT 'video_processing_runs', COUNT(*) FROM video_processing_runs
UNION ALL SELECT 'video_events', COUNT(*) FROM video_events
UNION ALL SELECT 'video_final_boxes', COUNT(*) FROM video_final_boxes
UNION ALL SELECT 'video_final_pallets', COUNT(*) FROM video_final_pallets
UNION ALL SELECT 'video_processing_metrics', COUNT(*) FROM video_processing_metrics;

-- Must return dispatched_boxes = 0.
SELECT COUNT(*) AS dispatched_boxes FROM boxes WHERE box_status = 'DISPATCHED';

-- Must return dispatched_orders = 0.
SELECT COUNT(*) AS dispatched_orders FROM orders WHERE order_status = 'DISPATCHED';

-- Must return lifecycle_rows = 0.
SELECT COUNT(*) AS lifecycle_rows FROM order_lifecycle_events;

-- Must also return dispatched_lifecycle_rows = 0.
SELECT COUNT(*) AS dispatched_lifecycle_rows FROM order_lifecycle_events WHERE UPPER(lifecycle_status) LIKE '%DISPATCH%';

-- Known video identities must all exist and remain RECEIVED before inference.
SELECT box_code, box_status FROM boxes WHERE box_code IN ('BOX_120','BOX_283','BOX_305','BOX_428','BOX_468','BOX_500','BOX_724','BOX_737','BOX_849') ORDER BY box_code;

-- Latest stage distribution used by the dashboard.
WITH latest_box_event AS (
    SELECT ole.* FROM order_lifecycle_events ole
    JOIN (
        SELECT box_id, MAX(order_lifecycle_event_id) AS latest_event_id
        FROM order_lifecycle_events WHERE box_id IS NOT NULL GROUP BY box_id
    ) x ON x.latest_event_id = ole.order_lifecycle_event_id
)
SELECT lifecycle_status, COUNT(*) AS boxes FROM latest_box_event GROUP BY lifecycle_status ORDER BY boxes DESC;

SELECT '503-BOX SEED COMPLETE - LIFECYCLE EMPTY - READY FOR EVENT PROCESSOR TEST' AS status;
